function text(content) {
  return new TextDisplayBuilder().setContent(content);
}

function separator() {
  return new SeparatorBuilder()
    .setDivider(true)
    .setSpacing(SeparatorSpacingSize.Small);
}

function makeContainer({ title, body, accent = COLORS.neutral, buttons = [] }) {
  const container = new ContainerBuilder()
    // Paradise branding: use one neutral grey sidebar on every V2 panel/message.
    .setAccentColor(COLORS.neutral)
    .addTextDisplayComponents(
      text(`# ${title}`),
      text(body),
    );

  if (buttons.length) {
    const row = new ActionRowBuilder().addComponents(...buttons);
    container
      .addSeparatorComponents(separator())
      .addActionRowComponents(row);
  }

  // Global Paradise footer banner: always the final component.
  container
    .addSeparatorComponents(separator())
    .addMediaGalleryComponents(footerGallery());

  return container;
}

function supportUrl(guildId) {
  return `https://discord.com/channels/${guildId}/${CONFIG.supportChannelId}`;
}

