function storePendingInquiry(userId, inquiry) {
  pendingSupportInquiries.set(userId, {
    inquiry,
    expiresAt: Date.now() + SUPPORT_INQUIRY_TTL_MS,
  });
}

function getPendingInquiry(userId) {
  const pending = pendingSupportInquiries.get(userId);
  if (!pending) return null;

  if (pending.expiresAt <= Date.now()) {
    pendingSupportInquiries.delete(userId);
    return null;
  }

  return pending.inquiry;
}


